    return out

def parse_tree(data):
    # entries: b"<mode> <name>\0<20-byte sha>" (mode octal ascii; trees '40000')
    out=[]
    i=0
    while i < len(data):
        sp=data.index(b' ', i); mode=data[i:sp].decode()
        nul=data.index(b'\0', sp); name=data[sp+1:nul].decode()
        sha=data[nul+1:nul+21]
        out.append((mode,name,sha))
        i=nul+21
    return out

