    typ,data=ps.read(bytes.fromhex(sha_hex))
    return typ,data

def tree_lookup(tree_sha, path_parts):
    typ,data=get(tree_sha)
    assert typ==2, typ  # tree
    ents=parse_tree(data)
    d=dict((n,(m,s)) for m,n,s in ents)
    head=path_parts[0]
    if head not in d:
        return None
    m,s=d[head]
    if len(path_parts)==1:
        return s.hex(), m
    typ2,data2=get(s.hex())
    return tree_lookup(s.hex(), path_parts[1:])

